// File: composer.json (tracked)
{
  "name": "my-plugin",
  "require": {
    "vendor/package": "^2.0"
  }
}

// File: composer.lock (tracked — exact versions, reproducible)
{
  "packages": [
    {
      "name": "vendor/package",
      "version": "2.4.3",  // Exact version, not a range
      ...
    }
  ]
}

# Result: deterministic builds
$ composer install
# uses composer.lock; all environments get vendor/package@2.4.3
$ git status
# nothing to commit; lock file is already in git

