// CORRECT — all fields declared, type + required enforced by the Abilities API
wp_register_ability( 'my-plugin/delete-post', [
    'label'              => 'Delete Post',
    'description'        => 'Deletes a post by ID',
    'input_schema'       => [
        'type'       => 'object',
        'properties' => [
            'post_id' => [
                'type'        => 'integer',
                'description' => 'The ID of the post to delete',
                'minimum'     => 1,
            ],
        ],
        'required'             => [ 'post_id' ],
        'additionalProperties' => false,  // reject unknown fields
    ],
    'execute_callback'   => function( $input ) {
        // $input['post_id'] is guaranteed to be a positive integer by the schema
        return wp_delete_post( $input['post_id'], true ) !== false;
    },
    'permission_callback' => function() { return current_user_can( 'delete_posts' ); },
    'meta' => [ 'mcp' => [ 'public' => true, 'type' => 'tool' ] ],
] );

