    // wp_get_loading_optimization_attributes() returns array e.g. ['loading' => 'lazy', 'decoding' => 'async']
    $opt_attrs = wp_get_loading_optimization_attributes(
        'img',
        array(
            'context'        => 'the_content',
            'width'          => isset( $attr['width'] ) ? (int) $attr['width'] : 0,
            'height'         => isset( $attr['height'] ) ? (int) $attr['height'] : 0,
