// theme.json — declarative, editor-aware, no PHP required (WP 6.5+)
{
  "version": 3,
  "settings": {
    "blocks": {
      "core/button": {
        "color": { "palette": false },
        "typography": { "fontFamilies": false }
      },
      "core/heading": {
        "color": { "palette": true }
      }
    }
  }
}

my-theme/
  /parts/                   ← correct: WordPress reads template parts from here
    header.html
    footer.html
