    archive.html

// theme.json — register parts for the editor
{
  "templateParts": [
    { "name": "header", "title": "Header", "area": "header" },
    { "name": "footer", "title": "Footer", "area": "footer" }
  ]
}

// block.json — declarative auto-insertion via Block Hooks API (WP 6.5+)
{
  "name": "my-plugin/cart-icon",
  "title": "Cart Icon",
  "category": "widgets",
  "blockHooks": {
    "core/navigation": "after"
  }
}

// PHP (optional): conditional insertion only when WooCommerce is active
add_filter( 'hooked_block_types', function( $block_types, $position, $anchor_block ) {
    if ( $anchor_block['blockName'] === 'core/navigation'
         && $position === 'after'
         && function_exists( 'WC' ) ) {
        $block_types[] = 'my-plugin/cart-icon';
    }
    return $block_types;
}, 10, 3 );

// /styles/blocks/button-ghost.json — single file, no PHP required (WP 6.6+)
{
  "blockTypes": [ "core/button" ],
  "name": "ghost",
  "label": "Ghost",
  "styles": {
    "color": {
      "background": "transparent",
      "text": "#0073aa"
    },
    "border": {
      "width": "2px",
      "color": "#0073aa",
      "style": "solid"
    },
    ":hover": {
      "color": {
        "background": "#0073aa",
        "text": "#ffffff"
      }
    }
  }
}
